using System.Diagnostics;
using System.Globalization;
using Vocaterra.Nlp.ContentBuilder;
using Xunit.Abstractions;
using NlpLexicon = Vocaterra.Nlp.Language.Lexicon.Lexicon;

namespace Vocaterra.Nlp.Content.Tests;

/// <summary>
/// Invariants of the imported lexicon that ships in the sample bundle (<c>lexicon/wiktionary-es.json</c> and its sidecar), plus the size and load-time gates.
/// The file is generated by <c>Vocaterra.Nlp.ContentBuilder import-lexicon</c> from sources that are not in the repository, so these tests check what can be checked
/// without them: that nobody edited the file by hand, that it agrees with its sidecar and with the hand-authored lexicons, and that it is sound.
/// </summary>
public class GeneratedLexiconTests(ITestOutputHelper output)
{
    private const string GeneratedPath = "lexicon/wiktionary-es.json";
    private const string SidecarPath = "lexicon/wiktionary-es.source.json";

    /// <summary>The size gate for a lexicon file (the plan allows 15 MB).</summary>
    private const long MaxLexiconBytes = 15 * 1024 * 1024;

    private static string Read(string relative)
    {
        return File.ReadAllText(Path.Combine(TestSupport.BundleDir, relative.Replace('/', Path.DirectorySeparatorChar))).Replace("\r\n", "\n", StringComparison.Ordinal);
    }

    private static LexiconSourceInfo Sidecar => TestSupport.Bundle.LexiconSources[SidecarPath];

    // The generated file is parsed once for all the tests of this class.
    private static readonly string GeneratedText = Read(GeneratedPath);

    private static readonly NlpLexicon Imported = SpanishLexicon.Load(GeneratedText);

    [Fact]
    public void TheFileIsExactlyWhatTheImporterWritesForItsOwnEntries()
    {
        // A hand edit, a different formatter or an unsorted entry would change the text.
        Assert.Equal(KaikkiImporter.ToJson(Imported.Entries), GeneratedText);
    }

    [Fact]
    public void TheFileIsMarkedAsImportedAndItsSidecarNamesTheCurrentImporter()
    {
        Assert.Equal(KaikkiImporter.GeneratedBy, Imported.GeneratedBy);
        Assert.Equal(
            KaikkiImporter.ImporterVersion,
            Sidecar.ImporterVersion);
    }

    [Fact]
    public void TheSidecarPinsTheSourcesByUrlHashAndDate()
    {
        var kaikki = Sidecar.Sources.Single(source => source.Id == "kaikki-es");
        var frequency = Sidecar.Sources.Single(source => source.Id == "frequency-es-50k");

        Assert.Equal("https://kaikki.org/dictionary/Spanish/kaikki.org-dictionary-Spanish.jsonl", kaikki.Url);
        Assert.Contains("/hermitdave/FrequencyWords/", frequency.Url, StringComparison.Ordinal);
        Assert.Matches("/[0-9a-f]{40}/content/2018/es/es_50k.txt$", frequency.Url);
        Assert.All(Sidecar.Sources, source =>
        {
            Assert.Equal(64, source.Sha256.Length);
            Assert.True(source.Bytes > 0 && source.Lines > 0);
            Assert.True(DateOnly.TryParseExact(source.RetrievedOn, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out _));
            Assert.Contains("CC-BY-SA", source.License, StringComparison.Ordinal);
        });
        Assert.Equal(50_000, frequency.Lines);
    }

    [Fact]
    public void TheSidecarParametersMatchWhatTheFileHolds()
    {
        var lexicon = Imported;

        Assert.NotNull(Sidecar.Parameters.Top);
        Assert.Equal(Sidecar.Parameters.Top, lexicon.Lemmas.Count);
        Assert.Equal(lexicon.Lemmas.Count, Sidecar.OutputLemmas);
        Assert.Equal(lexicon.Entries.Count, Sidecar.OutputEntries);
        Assert.Equal("frequency-es-50k", Sidecar.Parameters.FrequencySourceId);
        Assert.Equal(["game.json", "seed.json", "supplement.json"], Sidecar.Parameters.HandAuthoredFiles);
        Assert.Equal(lexicon.Entries.Count, Sidecar.Report.EntriesByPartOfSpeech.Values.Sum());
    }

    [Fact]
    public void TheFileIsUnderTheSizeGate()
    {
        var bytes = new FileInfo(Path.Combine(TestSupport.BundleDir, "lexicon", "wiktionary-es.json")).Length;

        output.WriteLine($"lexicon/wiktionary-es.json: {bytes} bytes, {Sidecar.OutputEntries} entries, {Sidecar.OutputLemmas} lemmas");
        Assert.True(bytes < MaxLexiconBytes, $"The generated lexicon is {bytes} bytes; the gate is {MaxLexiconBytes}.");
    }

    [Fact]
    public void TheImportLeavesTheHandAuthoredWordsAlone()
    {
        var hand = HandAuthoredLemmas.Read(Path.Combine(TestSupport.BundleDir, "lexicon"));
        var imported = Imported;

        var expectedFiles = Directory.EnumerateFiles(Path.Combine(TestSupport.BundleDir, "lexicon"), "*.json")
            .Select(path => Path.GetFileName(path))
            .Where(name => !name.EndsWith(".source.json", StringComparison.Ordinal) && name != "wiktionary-es.json")
            .Order(StringComparer.Ordinal)
            .ToArray();
        Assert.Equal(expectedFiles, hand.FileNames);
        var redefined = imported.Entries
            .Where(entry => entry.Pos != "verb" && hand.Lemmas.Contains(entry.Lemma))
            .Select(entry => $"{entry.Form} ({entry.Lemma}/{entry.Pos})")
            .Distinct(StringComparer.Ordinal)
            .Take(20)
            .ToArray();
        var reserved = imported.Entries
            .Where(entry => hand.FunctionWordForms.Contains(entry.Form))
            .Select(entry => $"{entry.Form} ({entry.Lemma}/{entry.Pos})")
            .Distinct(StringComparer.Ordinal)
            .Take(20)
            .ToArray();

        Assert.True(redefined.Length == 0, "Non-verb entries for lemmas the hand-authored lexicon defines: " + string.Join(", ", redefined));
        Assert.True(reserved.Length == 0, "Entries spelled like a hand-authored function word: " + string.Join(", ", reserved));
    }

    [Fact]
    public void TheMergedLexiconKeepsTheHandAuthoredGendersOfTheBundleNouns()
    {
        var lexicon = TestSupport.Bundle.Lexicon;

        foreach (var (word, gender) in new[] { ("espada", "f"), ("escudo", "m"), ("flecha", "f"), ("arco", "m"), ("bloque", "m"), ("lámpara", "f"), ("seta", "f"), ("río", "m") })
        {
            Assert.All(lexicon.Lookup(word).Where(static reading => reading.Pos == "noun"), reading => Assert.Equal(gender, reading.Gender));
        }
    }

    [Theory]
    [InlineData("conozco", "conocer", "1", "sg", "pres", "ind")]
    [InlineData("pido", "pedir", "1", "sg", "pres", "ind")]
    [InlineData("pidió", "pedir", "3", "sg", "pret", "ind")]
    [InlineData("duermo", "dormir", "1", "sg", "pres", "ind")]
    [InlineData("hablaremos", "hablar", "1", "pl", "fut", "ind")]
    [InlineData("hablaría", "hablar", "1", "sg", "cond", "ind")]
    public void VerbFormsHaveTheirPersonNumberTenseAndMood(string form, string lemma, string person, string number, string tense, string mood)
    {
        Assert.Contains(TestSupport.Bundle.Lexicon.Lookup(form), reading => reading.Lemma == lemma && reading.Pos == "verb" && reading.Person == person
            && reading.Number == number && reading.Tense == tense && reading.Mood == mood);
    }

    [Theory]
    [InlineData("mujeres", "mujer", "pl", "f")]
    [InlineData("ciudades", "ciudad", "pl", "f")]
    [InlineData("hombre", "hombre", "sg", "m")]
    [InlineData("buena", "bueno", "sg", "f")]
    [InlineData("buenos", "bueno", "pl", "m")]
    public void NounsAndAdjectivesHaveTheirGenderAndNumber(string form, string lemma, string number, string gender)
    {
        Assert.Contains(TestSupport.Bundle.Lexicon.Lookup(form), reading => reading.Lemma == lemma && reading.Number == number && reading.Gender == gender);
    }

    [Fact]
    public void NoImportedEntryIsAnInflectedFormPageOrAMultiWordExpression()
    {
        var imported = Imported;

        // The lemma of a verb is an infinitive; no form contains a space, a hyphen or a digit.
        Assert.All(imported.Entries.Where(static entry => entry.Pos == "verb"), entry => Assert.Matches("(ar|er|ir|ír)(se)?$", entry.Lemma));
        Assert.All(imported.Entries, entry => Assert.All(entry.Form, character => Assert.True(char.IsLetter(character), $"'{entry.Form}' contains '{character}'")));
        Assert.DoesNotContain(imported.Entries, entry => entry.Pos == "art" || entry.Pos == "num");
    }
}

/// <summary>
/// The lexicon load's CPU-time budget (M100). It runs alone in the timing collection, so no other test of the assembly is loading the machine while it measures.
/// </summary>
[Collection(TimingCollection.Name)]
[Trait(TestSpeed.Category, TestSpeed.Timing)]
public class GeneratedLexiconLoadTimeTests(ITestOutputHelper output)
{
    // Measured (M100, the sample bundle, one run at load about 10): the load takes 541 ms of CPU time, the fastest of three (582, 711, 541). The budget is twice that.
    // B29a: re-set from Release, measured alone as the timing step runs it (the load is cold there; inside the full suite it took 253): 592 to 639 ms of CPU time, the fastest of three; the budget is twice the largest (was 1082).
    private static readonly double LoadBudgetMilliseconds = Vocaterra.Nlp.Tests.TimingFactor.Scale(1280);

    [Fact]
    [Trait(TestSpeed.Trait, TestSpeed.Slow)]
    public void LoadingTheBundleIsFastEnough()
    {
        // The CPU time of this process (any thread) while the load runs, the fastest of three attempts (M100): another process's load does not count
        // against it, and a real slowdown adds CPU time in every attempt. Measured on the sample bundle (see docs/nlp/findings.md, M100).
        var attempts = new List<double>();
        for (var run = 0; run < 3; run++)
        {
            attempts.Add(CpuMilliseconds(() => SpanishContent.Load(TestSupport.BundleDir, new ContentLoadOptions { VerifyHashes = true })));
        }

        var fastest = attempts.Min();
        output.WriteLine($"ContentLoader.Load with hash verification, CPU time: {string.Join(", ", attempts.Select(ms => ms.ToString("F0", CultureInfo.InvariantCulture)))} ms (fastest {fastest:F0} ms)");

        Assert.True(fastest < LoadBudgetMilliseconds, $"Loading the bundle takes {fastest:F0} ms of CPU time; the budget is {LoadBudgetMilliseconds:F0} ms.");
    }

    private static double CpuMilliseconds(Action action)
    {
        using var process = Process.GetCurrentProcess();
        var before = process.TotalProcessorTime;
        action();
        process.Refresh();
        return (process.TotalProcessorTime - before).TotalMilliseconds;
    }
}
